/* Compact self-contained RTL page. No CDN or network asset dependency. */
const char baison_home_page[] =
"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>BAISON | إعداد الاتصال</title><style>"
":root{color-scheme:dark;--base:#0d1527;--card:#18243a;--line:#33445c;--light:#eef6ff;--dim:#a4b4cf;--aqua:#48dac9}"
"*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0%,#25415b,var(--base) 62%);color:var(--light);font:15px Tahoma,Arial,sans-serif;min-height:100vh}"
".wrap{max-width:730px;margin:auto;padding:28px 16px 50px}"
"header{display:flex;justify-content:space-between;gap:12px;align-items:center;padding-bottom:22px;border-bottom:1px solid var(--line)}"
".brand{display:flex;gap:12px;align-items:center}.logo{display:grid;place-items:center;border-radius:15px;background:linear-gradient(145deg,#38e2bf,#369aff);width:48px;height:48px;color:#09203d;font-weight:bold;font-size:21px}"
"small,.hint{color:var(--dim)}h1{font-size:23px;margin:0 0 5px}h2{font-size:18px;margin:0 0 10px}"
".pill{font-size:12px;background:#1b3841;border:1px solid #295e67;color:#88e6cd;padding:7px 10px;border-radius:16px}"
"section{background:linear-gradient(160deg,#1c2a43,#151f32);padding:22px;margin-top:18px;border:1px solid var(--line);border-radius:18px;box-shadow:0 16px 35px #0003}"
"label{display:block;margin:13px 0 7px;color:#dbe5f4;font-size:13px}"
"input,select{display:block;width:100%;padding:13px 12px;border:1px solid #405570;background:#10192b;border-radius:10px;color:var(--light);font:inherit;outline:none}input:focus,select:focus{border-color:var(--aqua)}"
"button,.btn{font:inherit;cursor:pointer;background:#26c6ac;color:#092a32;padding:12px 17px;border:0;border-radius:10px;font-weight:bold;display:inline-block;text-decoration:none}"
"button.secondary,.btn.secondary{background:#293b56;color:var(--light);border:1px solid var(--line)}button.warn{background:#713741;color:#fff}"
".actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:19px}.row{display:flex;justify-content:space-between;align-items:center;gap:12px}"
"#notice{margin-top:12px;white-space:pre-wrap;color:#80e9cc;min-height:22px}"
".kv{background:#102038;border-radius:12px;padding:12px;line-height:2;color:#bdcde2}"
"#passbox{position:relative}.sub{font-size:12px;color:var(--dim);line-height:1.7}"
"a{color:#80e9cd}footer{text-align:center;padding:28px 0 0;color:#8193ad;font-size:12px}"
"@media(max-width:500px){header{align-items:start}h1{font-size:20px}section{padding:16px}.wrap{padding-top:17px}}"
"</style></head><body><main class=\"wrap\">"
"<header><div class=\"brand\"><div class=\"logo\">B</div><div><h1>BAISON W70</h1><small>لوحة الاتصال والتحكم • إصدار V12</small></div></div><span class=\"pill\" id=\"state\">جار الفحص...</span></header>"
"<section><div class=\"row\"><div><h2>الاتصال بالشبكة</h2><div class=\"sub\">اختر شبكة Wi-Fi أو أدخل اسمها يدوياً، ثم احفظ الإعدادات.</div></div><button class=\"secondary\" onclick=\"scan()\">بحث</button></div>"
"<label>الشبكات المتاحة</label><select id=\"networks\" onchange=\"pick()\"><option value=\"\">اضغط بحث لعرض الشبكات</option></select>"
"<label>اسم شبكة Wi-Fi (SSID)</label><input id=\"ssid\" maxlength=\"32\" placeholder=\"اسم الشبكة\" autocomplete=\"off\">"
"<label>كلمة المرور</label><input id=\"password\" type=\"password\" maxlength=\"63\" placeholder=\"8 أحرف على الأقل؛ اتركها فارغة للشبكات المفتوحة\" autocomplete=\"new-password\">"
"<div class=\"actions\"><button onclick=\"save()\">حفظ واتصال</button><button class=\"secondary\" onclick=\"scan()\">تحديث القائمة</button></div>"
"<div id=\"notice\"></div><div class=\"sub\">بعد الحفظ ستعيد القطعة التشغيل. قد يتغير عنوان IP، وتبقى شبكة إعداد BAISON متاحة.</div></section>"
"<section><h2>معلومات القطعة</h2><div id=\"info\" class=\"kv\">جار تحميل الحالة...</div><div class=\"actions\"><a class=\"btn secondary\" href=\"/status\">حالة النظام</a><a class=\"btn secondary\" href=\"/api/commands\">الأوامر</a><a class=\"btn secondary\" href=\"/settings\">تعديل الإعدادات</a><a class=\"btn secondary\" href=\"/api/read?cmd=QPIGS\">بيانات الإنفرتر</a></div></section>"
"<section><h2>إدارة الجهاز</h2><div class=\"sub\">Restart يعيد تشغيل القطعة فقط. Reset Wi-Fi يمسح اسم الشبكة وكلمة مرورها المحفوظين دون حذف البرنامج أو إعدادات الإنفرتر.</div>"
"<div class=\"actions\"><button class=\"secondary\" onclick=\"act('restart')\">إعادة تشغيل</button><button class=\"warn\" onclick=\"act('forget')\">مسح Wi-Fi المحفوظة</button><a class=\"btn secondary\" href=\"/hide\">تحديث Firmware</a></div></section>"
"<section><h2>فحص أوامر الإنفرتر</h2><div class=\"sub\">القراءة متاحة محلياً. أوامر التعديل تتطلب موافقة صريحة وتفعيل محلي، ولا ينبغي تغيير قيم البطارية دون معرفة المواصفات.</div>"
"<label>أمر القراءة</label><select id=\"cmd\"><option>QPIGS</option><option>QPIRI</option><option>QMOD</option><option>QID</option><option>QVFW</option><option>QFLAG</option><option>QPIWS</option><option>QDI</option><option>QMCHGCR</option><option>QMUCHGCR</option></select>"
"<div class=\"actions\"><button class=\"secondary\" onclick=\"read()\">تنفيذ قراءة</button></div><pre id=\"reading\" class=\"kv\" dir=\"ltr\" style=\"white-space:pre-wrap;word-break:break-all\">جاهز</pre>"
"</section><footer>Developed by: MT_RADIUS 2020-<span id=\"yr\"></span></footer></main>"
"<script>"
"const $=s=>document.querySelector(s), msg=t=>$('#notice').textContent=t;"
"$('#yr').textContent=new Date().getFullYear();"
"async function api(url,options){const r=await fetch(url,options);const txt=await r.text();if(!r.ok)throw Error(txt||r.status);return txt}"
"async function load(){try{const a=JSON.parse(await api('/api/wifi/status'));$('#state').textContent=a.connected?'متصل':'إعداد الشبكة';$('#info').textContent='شبكة القطعة: '+a.ap+'\\nWi-Fi المحفوظة: '+(a.ssid||'لا يوجد')+'\\nحالة الاتصال: '+(a.connected?'متصل':'غير متصل')+'\\nقوة الإشارة: '+a.rssi; if(a.ssid)$('#ssid').value=a.ssid}catch(e){$('#state').textContent='غير متاح';$('#info').textContent=String(e)}}"
"async function scan(){msg('جار البحث عن الشبكات...');try{let a=JSON.parse(await api('/api/wifi/scan'));const sel=$('#networks');sel.replaceChildren();let opt=document.createElement('option');opt.value='';opt.textContent='اختر الشبكة';sel.append(opt);for(let n of a.networks||[]){let o=document.createElement('option');o.value=n.ssid;o.textContent=n.ssid+' ('+n.rssi+' dBm)';sel.append(o)}msg('تم العثور على '+(a.networks||[]).length+' شبكة')}catch(e){msg('تعذر البحث: '+e.message)}}"
"function pick(){if($('#networks').value)$('#ssid').value=$('#networks').value}"
"async function save(){let ssid=$('#ssid').value,p=$('#password').value;if(!ssid||ssid.length>32){msg('أدخل اسم شبكة صحيح');return}if(p.length>0&&p.length<8){msg('كلمة المرور قصيرة');return}if(!confirm('حفظ إعدادات الشبكة وإعادة تشغيل القطعة؟'))return;try{const body=new URLSearchParams({ssid,password:p});msg(await api('/api/wifi/save',{method:'POST',body,headers:{'X-W70-Action':'confirm'}}))}catch(e){msg(e.message)}}"
"async function act(action){if(!confirm(action==='forget'?'مسح شبكة Wi-Fi المحفوظة وإعادة تشغيل القطعة؟':'إعادة تشغيل القطعة الآن؟'))return;try{msg(await api('/api/system/'+action,{method:'POST',headers:{'X-W70-Action':'confirm'}}))}catch(e){msg(e.message)}}"
"async function read(){try{$('#reading').textContent=JSON.stringify(JSON.parse(await api('/api/read?cmd='+$('#cmd').value)),null,2)}catch(e){$('#reading').textContent=e.message}}"
"load();"
"</script></body></html>";
